import{_ as r,C as s,o as c,c as l,j as o,a as d,E as t,a2 as i}from"./chunks/framework.BxGh02fV.js";const _=JSON.parse('{"title":"Code and stacks","description":"","frontmatter":{"title":"Code and stacks"},"headers":[],"relativePath":"en/agent/code.md","filePath":"en/agent/code.md"}'),n={name:"en/agent/code.md"};function h(f,a,u,k,m,p){const e=s("Ask");return c(),l("div",null,[a[0]||(a[0]=o("h1",{id:"code-and-stacks",tabindex:"-1"},[d("Code and stacks "),o("a",{class:"header-anchor",href:"#code-and-stacks","aria-label":'Permalink to "Code and stacks"'},"​")],-1)),a[1]||(a[1]=o("p",null,[d("A stack (a module) is a part of your code: its folder under "),o("code",null,"codebase/"),d(", its model, its languages. You come to this path to declare a module, choose a model, scaffold the starting code, build, run the tests, tidy up, or bring the work of a worktree back into the repository.")],-1)),a[2]||(a[2]=o("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[d("What you ask the agent "),o("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),t(e,{say:"Which stack models exist, and what does the rust model contain?",verb:"effortless_stack_model_list",family:"stacks"}),t(e,{say:"Add an api module with the node model.",verb:"effortless_stack_add",family:"stacks",args:'{"id":"api","scaffold_template":"node"}'}),t(e,{say:"Which stacks are declared in this project?",verb:"effortless_stack_list",family:"stacks"}),t(e,{say:"The api module is in Rust and TypeScript: declare it.",verb:"effortless_stack_declare_languages",family:"stacks",args:'{"stack_id":"api","languages":[{"id":"rust"},{"id":"typescript"}]}'}),t(e,{say:"Which command runs the tests of the api module? And the lint?",verb:"effortless_stack_cycle",family:"stacks",args:'{"stack_id":"api","kind":"test"}'}),t(e,{say:"Build the desktop module.",verb:"effortless_stack_build",family:"stacks",args:'{"stack_id":"desktop"}'}),t(e,{say:"Show me what the housekeeping would do on desktop, without deleting anything.",verb:"effortless_stack_housekeeping",family:"stacks",args:'{"stack_id":"desktop","apply":false}'}),t(e,{say:"Move the code lying at the root under codebase/.",verb:"effortless_codebase_relocate",family:"installation",args:'{"dry_run":false}'}),t(e,{say:"Bring the work of the ../wt-api worktree back into the repository, with pnpm test as the bar.",verb:"effortless_worktree_reintegrate",family:"stacks",args:'{"worktree_path":"../wt-api","bar":{"test":"pnpm test"}}'}),a[3]||(a[3]=i('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="choose-a-stack-model" tabindex="-1">Choose a stack model <a class="header-anchor" href="#choose-a-stack-model" aria-label="Permalink to &quot;Choose a stack model&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/stacks.html#stack-model-list"><code>effortless_stack_model_list</code></a> lists the models: those shipped with Effortless (<code>rust</code>, <code>node</code>, <code>python</code>, <code>generic</code>, <code>tauri</code>, <code>react</code>, <code>tauri-react</code>, <code>tauri-react-tailwind</code>) and those in the project store. It works before any project exists; the &quot;Get started&quot; path uses it too.</li><li><a href="/Effortless/en/reference/mcp/stacks.html#stack-model-show"><code>effortless_stack_model_show</code></a> with <code>model_id</code> details a model: its variables, its build strategy and its cycle commands (test, lint, run).</li></ol><h3 id="declare-a-module-and-its-languages" tabindex="-1">Declare a module and its languages <a class="header-anchor" href="#declare-a-module-and-its-languages" aria-label="Permalink to &quot;Declare a module and its languages&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/stacks.html#stack-add"><code>effortless_stack_add</code></a> with <code>id</code>. It declares the stack (default path <code>codebase/&lt;id&gt;/</code>), scaffolds the folder and applies the model given by <code>scaffold_template</code>, with the variables from <code>vars</code>. A <code>path</code> outside the project makes it an external module: <code>git: true</code> if that module has its own repository, to be tracked like the project&#39;s (drift, hook); without <code>git: true</code>, these are shared sources, left on the side — see <a href="/Effortless/en/guide/setup.html">Choosing your setup</a>.</li><li>The languages are pre-filled by the model; <code>languages</code> passed in the call replaces them. The standards of the declared languages are written to <code>.ai/ndd/</code>; those that are missing are named in the response.</li><li><a href="/Effortless/en/reference/mcp/stacks.html#stack-declare-languages"><code>effortless_stack_declare_languages</code></a> then corrects the languages: the new declaration replaces the previous one, it does not merge. An empty list says &quot;no standard&quot;.</li><li><a href="/Effortless/en/reference/mcp/stacks.html#stack-list"><code>effortless_stack_list</code></a> reads the declared stacks back.</li></ol><h3 id="scaffold" tabindex="-1">Scaffold <a class="header-anchor" href="#scaffold" aria-label="Permalink to &quot;Scaffold&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/stacks.html#scaffold-list"><code>effortless_scaffold_list</code></a> lists the templates available in the project store.</li><li><a href="/Effortless/en/reference/mcp/stacks.html#scaffold-apply"><code>effortless_scaffold_apply</code></a> with <code>template_id</code> and <code>target_dir</code> writes the template&#39;s files into a folder. Files already present are left intact and reported as skipped. <a href="/Effortless/en/reference/mcp/stacks.html#scaffold-apply-project"><code>effortless_scaffold_apply_project</code></a> does the same at the project root.</li><li>To bring your own template: <a href="/Effortless/en/reference/mcp/stacks.html#scaffold-format"><code>effortless_scaffold_format</code></a> returns the schema of a scaffold manifest, then <a href="/Effortless/en/reference/mcp/stacks.html#scaffold-import"><code>effortless_scaffold_import</code></a> with <code>path</code> imports it into the project store after validation.</li></ol><h3 id="build-and-run-the-cycle" tabindex="-1">Build and run the cycle <a class="header-anchor" href="#build-and-run-the-cycle" aria-label="Permalink to &quot;Build and run the cycle&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/stacks.html#stack-build"><code>effortless_stack_build</code></a> with <code>stack_id</code> runs the model&#39;s build command, from the stack&#39;s folder, and returns the status, the artifacts and the logs.</li><li><a href="/Effortless/en/reference/mcp/stacks.html#stack-cycle"><code>effortless_stack_cycle</code></a> with <code>stack_id</code> and <code>kind</code> (<code>test</code>, <code>lint</code> or <code>run</code>) returns the resolved command. It does not run it: the agent runs it afterwards.</li></ol><h3 id="tidy-up" tabindex="-1">Tidy up <a class="header-anchor" href="#tidy-up" aria-label="Permalink to &quot;Tidy up&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/stacks.html#stack-housekeeping"><code>effortless_stack_housekeeping</code></a> reports what the housekeeping policy declared in <code>languages[].housekeeping</code> would purge: what, how large, for which language. Without <code>apply</code>, it deletes nothing. The agent passes <code>apply: true</code> only after your agreement. <code>stack_id</code> limits the report to one stack.</p><h3 id="move-the-code-under-codebase" tabindex="-1">Move the code under <code>codebase/</code> <a class="header-anchor" href="#move-the-code-under-codebase" aria-label="Permalink to &quot;Move the code under `codebase/`&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/installation.html#codebase-relocate"><code>effortless_codebase_relocate</code></a> moves the code left at the root into <code>codebase/&lt;stack&gt;/</code> (the <code>default</code> stack without <code>stack_id</code>). It starts with a preview (<code>dry_run</code> is <code>true</code> by default); the agent runs it for real (<code>dry_run: false</code>) after your agreement. In <strong>Semi-auto</strong> mode it is disabled and says so.</p><h3 id="reintegrate-a-worktree" tabindex="-1">Reintegrate a worktree <a class="header-anchor" href="#reintegrate-a-worktree" aria-label="Permalink to &quot;Reintegrate a worktree&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/stacks.html#worktree-reintegrate"><code>effortless_worktree_reintegrate</code></a> with <code>worktree_path</code> (or <code>worktree_paths</code> for a multi-repository project) and <code>bar</code>, the check bar: an object that maps <code>test</code>, <code>lint</code>, <code>typecheck</code> or <code>build</code> to a command. The verb first commits the worktree&#39;s pending files, measures the bar in the worktree, and merges only if everything is green. After a successful merge, the worktree and its branch are removed, unless <code>keep_worktree: true</code>. The verb never creates a worktree.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>Modules declared in <code>effortless.json</code>, folders under <code>codebase/&lt;id&gt;/</code>, language standards in <code>.ai/ndd/</code>.</li><li>The <a href="/Effortless/en/guide/modules.html">Modules</a> screen shows each stack: languages, model, standards, version, delivery. It is read-only; stacks are declared by the agent or when the workspace is created.</li><li>For a reintegrated worktree: the work is merged into the repository, or nothing changed.</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>Unknown stack (language declaration, housekeeping)</td><td><code>stack:unknown</code></td><td>List the stacks with <code>effortless_stack_list</code>.</td></tr><tr><td>Unknown stack (build, cycle)</td><td><code>stacks:stackNotFound</code></td><td>Same action: <code>effortless_stack_list</code>.</td></tr><tr><td>Stack id already taken, or empty</td><td>&quot;stack id already exists&quot; / &quot;stack id required&quot;</td><td>Pick another <code>id</code>.</td></tr><tr><td>Malformed languages</td><td><code>stack:languagesMalformed</code> (the faulty entries are named)</td><td>Each language is an object <code>{ id, version, ndd }</code>.</td></tr><tr><td>Standard source neither <code>embedded</code> nor <code>git</code></td><td><code>stack:nddSourceRefused</code></td><td>Declare the source as <code>embedded</code> or <code>git</code>.</td></tr><tr><td>Stack without a model, for a build</td><td>&quot;the stack has no model (scaffold_template)&quot;</td><td>Declare the stack with a model.</td></tr><tr><td>Unknown cycle requested</td><td><code>stacks:cycleInvalid</code></td><td><code>kind</code> is <code>test</code>, <code>lint</code> or <code>run</code>.</td></tr><tr><td>Template not found</td><td><code>create:templateNotFound</code></td><td>List the templates with <code>effortless_scaffold_list</code>.</td></tr><tr><td>Invalid imported manifest</td><td>&quot;invalid manifest&quot; with the list of errors</td><td>Fix the manifest using <code>effortless_scaffold_format</code>.</td></tr><tr><td>Imported model that declares a command to run</td><td><code>create:anchorUntrusted</code></td><td>Remove the <code>anchor</code> key from the manifest, or take a shipped model (<code>effortless_stack_model_list</code>).</td></tr><tr><td>Folder to reintegrate is not a git worktree</td><td><code>worktree:notAWorktree</code></td><td>Create the worktree first: the verb never creates one.</td></tr><tr><td>Worktree on no branch</td><td><code>worktree:detachedHead</code></td><td>Put the worktree back on a branch.</td></tr><tr><td>No worktree given</td><td><code>worktree:noWorktree</code></td><td>Pass <code>worktree_path</code>, or <code>worktree_paths</code>.</td></tr><tr><td>The bar goes red</td><td><code>worktree:barRed</code> (the failing commands are named)</td><td>Fix in the worktree, then retry; nothing was reintegrated.</td></tr><tr><td>Untracked symbolic link in the worktree</td><td><code>worktree:untrackedSymlink</code></td><td>Ignore the link in <code>.gitignore</code> (pattern without a trailing slash) or remove it.</td></tr><tr><td>Merge conflict</td><td><code>worktree:mergeConflict</code> (files named)</td><td>Resolve the conflict in the worktree and retry; the merge was cancelled.</td></tr><tr><td>Partial merge across several repositories</td><td><code>worktree:partialMerge</code></td><td>Fix the cause, then retry on the failing worktree only.</td></tr></tbody></table>',19))])}const w=r(n,[["render",h]]);export{_ as __pageData,w as default};
